```python
if self.__frame == 0:
    if self.mode == "P" and LOADING_STRATEGY == LoadingStrategy.RGB_ALWAYS:
        if "transparency" in self.info:
            self.im.putpalettealpha(self.info["transparency"], 0)
            self.mode = "RGBA"
        else:
            self.mode = "RGB"
        self.im = self.im.convert(self.mode, Image.Dither.FLOYDSTEINBERG)
    return
```

